INSERT INTO public.source (id, title, source_type, author, edition, url, note)
SELECT id, title, source_type, author, edition, url, note FROM jsonb_populate_recordset(NULL::public.source, '[{"title": "旧五代史·卷98·张彦泽传·张式遭迫害", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/652233df546823980246fe2d04ddc59b70526578/content/books/zizhi-tongjian/vol-282/year-0941/part-01/sources/library/jiuwudaishi-098-zhang-shi/source.txt", "note": "《旧五代史》卷98·张彦泽传·张式遭迫害，段落 jiu-wudaishi-205deb4a7860-p002399；已核上下文及传主，纸本及异文待核。", "id": "80e3042c-3292-5c33-82db-427cf5330f0b"}, {"title": "资治通鉴·卷282·四部丛刊本第149页·941年后蜀任官", "source_type": "primary", "author": "司马光等", "edition": "维基文库四部丛刊本第149页固定修订1471325；逐字Wikitext保留，影印字形及纸本待核。", "url": "https://github.com/greed-216/histree/blob/652233df546823980246fe2d04ddc59b70526578/content/books/zizhi-tongjian/vol-282/year-0941/part-01/sources/library/tongjian-282-941-sibu-collation/source.txt", "note": "《资治通鉴》四部丛刊本卷282，第149页转录，维基文库固定修订1471325；同书电子版本校读，影印字形及纸本待核。", "id": "078be5d8-c35b-5336-9606-6138f59a6ce3"}, {"title": "新五代史·卷52·张彦泽传·张式遭迫害", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/652233df546823980246fe2d04ddc59b70526578/content/books/zizhi-tongjian/vol-282/year-0941/part-01/sources/library/xinwudaishi-052-zhang-shi/source.txt", "note": "《新五代史》卷52·张彦泽传·张式遭迫害，段落 xin-wudaishi-b08f244b9241-p002049；已核上下文及传主，纸本及异文待核。", "id": "b4ee08d5-17ef-5f82-b96a-697ae269697e"}, {"title": "资治通鉴·卷282·天福五年秋冬", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/c3ae4917b03ca0346efedf03bafabb5e360d93ab/content/books/zizhi-tongjian/vol-282/year-0940/part-03/sources/library/tongjian-282-940-autumn-winter/source.txt", "note": "《资治通鉴》卷282·天福五年秋冬，段落 zizhi-tongjian-a63549944a71-p003354；已核上下文及传主，纸本及异文待核。", "id": "67bbc261-6a53-5402-b019-4a8cc37d7ad4"}, {"title": "新五代史·卷51·安重荣传·吐谷浑归附", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/c3ae4917b03ca0346efedf03bafabb5e360d93ab/content/books/zizhi-tongjian/vol-282/year-0940/part-03/sources/library/xinwudaishi-051-an-chongrong-tuyuhun/source.txt", "note": "《新五代史》卷51·安重荣传·吐谷浑归附，段落 xin-wudaishi-b08f244b9241-p002001；已核上下文及传主，纸本及异文待核。", "id": "c388217f-0877-51f5-af6e-54670f3732ff"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "石敬瑭", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷271贞明五年条所见人物：石敬瑭。", "biography": null, "status": "draft", "id": "bf42d98c-7477-5be1-a767-867fe26cf617"}, {"name": "张澄", "aliases": ["張澄"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋供奉官。941年正月受石敬瑭派遣，带两千兵搜寻并驱逐并、镇、忻、代四州山谷中的吐谷浑部众。生卒年未载。", "biography": null, "status": "draft", "id": "78d918a0-9c7a-5e35-97f5-597c8ba8d549"}, {"name": "王延政", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：王延政，都教练使、赴建州抚慰者。", "biography": null, "status": "draft", "id": "83601670-f3dc-5559-b599-e39bda91eb6c"}, {"name": "王延羲", "aliases": ["王曦"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "闽国宗室，王继鹏的叔父，曾任左仆射、同平章事。939年被政变军队拥立，自称威武节度使、闽国王，更名王曦，改元永隆。生卒年暂未核实。", "biography": null, "status": "draft", "id": "e706d6ae-56f4-5e44-9d24-f3060ae87cbb"}, {"name": "张彦泽", "aliases": ["張彥澤"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "太原人，938年任镇国军节度使，在华州截击并杀死东行的凤翔叛军。生卒年本段未载。", "biography": null, "status": "draft", "id": "194d0f9a-3b17-5635-9741-dffc983ee32e"}, {"name": "张式", "aliases": ["張式"], "era": "五代十国", "birth_year": null, "death_year": 941, "description": "张彦泽的掌书记，曾受到信任。941年劝阻张彦泽杀子，遭射箭、谗言和追捕；李周为他上报朝廷后，仍被石敬瑭交还张彦泽，二月癸未在泾州遇害。新旧五代史对逃亡路线有异说。出生年未载。", "biography": null, "status": "draft", "id": "f0a85d86-b611-526b-8a8a-5263d0de38e3"}, {"name": "李周", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷272同光元年条所见人物：李周。", "biography": null, "status": "draft", "id": "80ce0eab-d01c-5ae2-ad19-5d2e34b7e3b5"}, {"name": "郑元昭", "aliases": ["鄭元昭"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "张彦泽的行军司马。941年前往后晋朝廷要求交还张式，并转述张彦泽的威胁。生卒年未载。", "biography": null, "status": "draft", "id": "f88f25cc-3719-598a-9583-1191e028e2b5"}, {"name": "李文谦", "aliases": ["李文謙"], "era": "五代十国", "birth_year": null, "death_year": 941, "description": "凉州留后。941年凉州发生军乱，李文谦闭门自焚而死。出生年及军乱原因未载。", "biography": null, "status": "draft", "id": "3819b62c-8cc5-5121-9cc0-0fe7f7fda2fd"}, {"name": "孟昶", "aliases": ["孟仁赞", "孟仁贊"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275天成二年条所见人物：孟昶，孟子、被迎者。", "biography": null, "status": "draft", "id": "666201f7-9186-590e-8d5b-2a4a605dba69"}, {"name": "赵廷隐", "aliases": ["趙廷隱"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷272同光元年条所见人物：赵廷隐。", "biography": null, "status": "draft", "id": "bc139832-e17d-51c1-b2c5-a6b9fcca1a14"}, {"name": "王处回", "aliases": ["王處回"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：王处回，为税官请免的中门副使。", "biography": null, "status": "draft", "id": "159fd2b3-759b-522a-a971-11356c6fe970"}, {"name": "张公铎", "aliases": ["張公鐸", "张公鐸"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：张公铎，义胜定元都知兵马使、后阵者。", "biography": null, "status": "draft", "id": "3fe095f0-3ed1-5a82-8dce-807120a0240b"}, {"name": "李昊", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷274同光三年条所见人物：李昊。", "biography": null, "status": "draft", "id": "ecf7855b-2568-576c-b0b9-58e6b1f120fa"}, {"name": "刘英图", "aliases": ["劉英圖"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后蜀散骑常侍。941年三月甲戌受孟昶任命，主管保宁军。生卒年未载。", "biography": null, "status": "draft", "id": "c62ff44e-d77a-5314-bce3-3ac5db5ff719"}, {"name": "崔銮", "aliases": ["崔鑾"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后蜀谏议大夫。941年三月甲戌受孟昶任命，主管武信军。生卒年未载。", "biography": null, "status": "draft", "id": "e1770bcf-55a4-5367-84e3-61ca66952330"}, {"name": "谢从志", "aliases": ["謝從志"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后蜀给事中。941年三月甲戌受孟昶任命，主管武泰军。生卒年未载。", "biography": null, "status": "draft", "id": "2d6314bc-995c-551d-a1b8-3e9bb48162ab"}, {"name": "张赞", "aliases": ["張讚", "张讚"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后蜀将作监。941年三月甲戌受孟昶任命，主管宁江军。电子底本将姓名中的字拆写为部件，同书四部丛刊本电子转录写作張讚，展示采用简体张赞，影印字形及纸本仍待核。生卒年未载。", "biography": null, "status": "draft", "id": "f0a0a7af-a4d2-55ce-90d2-c53b0ece5660"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "石敬瑭派张澄率两千兵搜寻并驱逐吐谷浑部众", "start_year": 941, "end_year": 941, "time_original": "941年正月丙寅", "dynasty": "五代十国", "description": "石敬瑭派供奉官张澄率两千兵，搜寻并、镇、忻、代四州山谷中的吐谷浑部众，驱逐他们返回原居地。", "phases": [], "location_name": "并、镇、忻、代四州山谷", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "a8c6e54f-9644-58c9-8fb5-5a71d64eaa12"}, {"title": "王延政修筑建州城，城周二十里", "start_year": 941, "end_year": 941, "time_original": "941年正月条下，具体日期未载", "dynasty": "五代十国", "description": "王延政修筑建州城，城周二十里。", "phases": [], "location_name": "建州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "446f7508-b1aa-596d-b0f4-dd650060d176"}, {"title": "王延政请求将建州设为威武军，并由自己任节度使", "start_year": 941, "end_year": 941, "time_original": "941年正月条下，具体日期未载", "dynasty": "五代十国", "description": "王延政请求将建州设为威武军，并由自己任节度使。", "phases": [], "location_name": "建州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "45a1a226-6b8e-52be-bc38-7a016fdd2607"}, {"title": "王延羲在建州设置镇安军，任王延政为节度使并封富沙王", "start_year": 941, "end_year": 941, "time_original": "941年正月条下，具体日期未载", "dynasty": "五代十国", "description": "王延羲在建州设置镇安军，任王延政为节度使并封富沙王。", "phases": [], "location_name": "建州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "a8a974cd-c8c2-5c46-929d-51f8eb43b2c7"}, {"title": "王延政自行将镇安军改称镇武军", "start_year": 941, "end_year": 941, "time_original": "941年正月条下，具体日期未载", "dynasty": "五代十国", "description": "王延政自行将镇安军改称镇武军。", "phases": [], "location_name": "建州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "220ea4e1-dd42-5964-b503-580c0f439149"}, {"title": "德胜口修建浮桥", "start_year": 941, "end_year": 941, "time_original": "941年二月壬辰", "dynasty": "五代十国", "description": "《资治通鉴》记，二月壬辰在德胜口修建浮桥。原文没有记明主持施工者、桥长或坐标。", "phases": [], "location_name": "德胜口", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "ec8d7f66-0f68-54d0-9b27-08091f6c4daa"}, {"title": "张式劝阻张彦泽杀死自己的儿子", "start_year": 941, "end_year": 941, "time_original": "941年二月癸未张式遇害以前，具体日期未载", "dynasty": "五代十国", "description": "张式劝阻张彦泽杀死自己的儿子。", "phases": [], "location_name": "五代十国", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "e628fd9e-268a-5753-8efa-712a97026240"}, {"title": "张彦泽因张式劝谏而发怒，向张式射箭", "start_year": 941, "end_year": 941, "time_original": "941年二月癸未以前，具体日期未载", "dynasty": "五代十国", "description": "张彦泽因张式劝谏而发怒，向张式射箭。", "phases": [], "location_name": "五代十国", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "00cb5bba-b616-5f0f-a351-efb8b383ee2f"}, {"title": "张式遭张彦泽左右进谗，告病离开", "start_year": 941, "end_year": 941, "time_original": "941年二月癸未以前，具体日期未载", "dynasty": "五代十国", "description": "张彦泽左右的人原本厌恶张式，又向张彦泽进谗。张式害怕，以生病为由离开。", "phases": [], "location_name": "五代十国", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "54a8642a-0e5d-5ada-8e18-502f0b47b7e0"}, {"title": "张彦泽派兵追捕张式", "start_year": 941, "end_year": 941, "time_original": "941年二月癸未以前，具体日期未载", "dynasty": "五代十国", "description": "张彦泽派兵追捕张式。", "phases": [], "location_name": "五代十国", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "673087b6-9f63-5865-a15d-3b973125b217"}, {"title": "张式到达邠州，李周向朝廷上报", "start_year": 941, "end_year": 941, "time_original": "941年二月癸未以前，具体日期未载", "dynasty": "五代十国", "description": "张式到达邠州，李周向朝廷上报。", "phases": [], "location_name": "邠州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "63416d2d-4584-5c5f-a3bc-c56df62ba456"}, {"title": "石敬瑭顾忌张彦泽，将张式流放商州", "start_year": 941, "end_year": 941, "time_original": "941年二月癸未以前，具体日期未载", "dynasty": "五代十国", "description": "石敬瑭顾忌张彦泽，将张式流放商州。", "phases": [], "location_name": "商州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "518a294f-0269-5aec-9b24-7662f4eb6010"}, {"title": "郑元昭到朝廷要求交还张式，并转述张彦泽的威胁", "start_year": 941, "end_year": 941, "time_original": "941年二月癸未以前，具体日期未载", "dynasty": "五代十国", "description": "张彦泽派行军司马郑元昭到朝廷要求交还张式。郑元昭说，如果张彦泽得不到张式，恐怕会出现难以预料的后果。", "phases": [], "location_name": "五代十国", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "c6156a3e-89de-5f6f-adde-6e170be9db9c"}, {"title": "石敬瑭将张式交给张彦泽", "start_year": 941, "end_year": 941, "time_original": "941年二月癸未以前，具体日期未载", "dynasty": "五代十国", "description": "石敬瑭将张式交给张彦泽。", "phases": [], "location_name": "五代十国", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": 